+inline bool ValidateKeyInnerAxesContiguous(gert::TilingContext *context, const gert::Stride *stride,
+                                           const gert::Shape &shape)
+{
+    if (stride == nullptr || stride->GetDimNum() != shape.GetDimNum()) {
+        return true;
