+    // int8 保持 2 级：K 源是每 stile 复用的 per-core scratch，AIV 下一 stile 的 cast
+    // 会重写该区，更深的预取与 cast 重写产生竞态（实测 STAGES=3 下 int8 崩溃）。
+    // L1 占用：A 32KB + 3×32KB B = 128KB / 512KB。
+    static constexpr uint32_t STAGES = STAGES_IN;
