+                                  dataCopyParams);
+            }
+        } else {
+            if (layoutSrc.stride(1) < STRIDE_LIMIT) {
+                if (layoutSrc.shape(0) != ELE_NUM_PER_C0 || layoutSrc.stride(1) != ELE_NUM_PER_C0) {
+                    intriParams.nValue = layoutSrc.shape(1);
