+    struct Params {};
+    Params params;
+
+    CATLASS_DEVICE
+    CopyL0CToGm() = default;
+
+    CATLASS_DEVICE
+    CopyL0CToGm(Params const &params_)
+        : params(params_) {};
+
+    CATLASS_DEVICE
+    void operator()(AscendC::GlobalTensor<ElementDst> const &dst, AscendC::LocalTensor<ElementSrc> const &src,
+                    LayoutDst const &dstLayout, LayoutSrc const &srcLayout, uint8_t unitFlag = 0)
