+        AscendC::FixpipeParamsV220 intriParams;
+
+        intriParams.nSize = srcLayout.orgShape(1);
+        intriParams.mSize = srcLayout.orgShape(0);
+        intriParams.srcStride = srcLayout.stride(3) / srcLayout.shape(2);
