+#ifndef CATLASS_MSA_LAYOUT_MATRIX_HPP
+#define CATLASS_MSA_LAYOUT_MATRIX_HPP
+
+#include "catlass/msa_catlass.hpp"
+#include "catlass/msa_coord.hpp"
