+#ifndef CATLASS_MSA_GEMM_COORD_HPP
+#define CATLASS_MSA_GEMM_COORD_HPP
+
+#include "catlass/msa_coord.hpp"
+
+namespace Catlass {
+
+/// Rank of a Gemm (M, N, K) coordinate.
+static constexpr int GEMM_COORD_RANK = 3;
+/// Rank of a 2-D matrix coordinate (e.g. MN / MK / KN).
+static constexpr int GEMM_MAT_RANK = 2;
+
+/// Shape of a matrix multiply-add operation
+template <
+    /// Rows of matrix product
+    uint32_t M_ = 1,
+    /// Columns of matrix product
+    uint32_t N_ = 1,
+    /// Inner dimension of matrix product
+    uint32_t K_ = 1>
+struct GemmShape {
+    static constexpr uint32_t M = M_;
+    static constexpr uint32_t N = N_;
+    static constexpr uint32_t K = K_;
+
+    static constexpr int64_t MN = M * N;
+    static constexpr int64_t MK = M * K;
+    static constexpr int64_t KN = N * K;
+    static constexpr int64_t MNK = M * N * K;
+
+    static constexpr int64_t COUNT = MNK;
+
+    /// Returns a Coord object
+    CATLASS_HOST_DEVICE
+    static Coord<GEMM_COORD_RANK> ToCoord()
+    {
+        return MakeCoord(M, N, K);
+    }
+
+    CATLASS_HOST_DEVICE
+    static Coord<GEMM_MAT_RANK> ToCoordMN()
+    {
+        return MakeCoord(M, N);
+    }
+
+    CATLASS_HOST_DEVICE
+    static Coord<GEMM_MAT_RANK> ToCoordMK()
+    {
+        return MakeCoord(M, K);
+    }
+
+    CATLASS_HOST_DEVICE
+    static Coord<GEMM_MAT_RANK> ToCoordKN()
+    {
+        return MakeCoord(K, N);
+    }
+};
+
+/// GemmCoord is a structure derived from Coord<GEMM_COORD_RANK> that specifies a location within the
+/// coordinate space of a Gemm problem.
+struct GemmCoord : public Coord<GEMM_COORD_RANK, uint32_t> {
+    /// Integer-valued index
+    using Index = uint32_t;
+
+    /// Base type is a Coord of rank=3
+    using Base = Coord<GEMM_COORD_RANK, Index>;
+
+    /// Gemm M dimension - rows of the output C matrix
+    static constexpr int M_INDEX = 0;
+
+    /// Gemm N dimension - columns of the output C matrix
+    static constexpr int N_INDEX = 1;
+
+    /// Gemm K dimension - inner dimension of the Gemm problem
+    static constexpr int K_INDEX = 2;
+
+    /// Default ctor
+    CATLASS_HOST_DEVICE
+    GemmCoord() {}
+
+    /// Constructs from Coord<GEMM_COORD_RANK> and a batch
+    CATLASS_HOST_DEVICE
+    GemmCoord(Coord<GEMM_COORD_RANK, Index> const &coord)
+        : Base(coord)
+    {}
+
+    /// Helper to construct from a K, N, M, batch variables
+    CATLASS_HOST_DEVICE
+    GemmCoord(Index m, Index n, Index k)
+        : Base(MakeCoord(m, n, k))
+    {}
+
+    /// Returns the Gemm M coordinate
+    CATLASS_HOST_DEVICE
+    Index const &m() const
+    {
+        return this->At(M_INDEX);
+    }
+
+    /// Returns reference to the Gemm M coordinate
+    CATLASS_HOST_DEVICE
+    Index &m()
+    {
+        return this->At(M_INDEX);
+    }
+
+    /// Returns the Gemm N coordinate
+    CATLASS_HOST_DEVICE
+    Index const &n() const
+    {
+        return this->At(N_INDEX);
+    }
+
+    /// Returns reference to the Gemm N coordinate
+    CATLASS_HOST_DEVICE
+    Index &n()
+    {
+        return this->At(N_INDEX);
+    }
+
+    /// Returns the Gemm K coordinate
+    CATLASS_HOST_DEVICE
+    Index const &k() const
+    {
+        return this->At(K_INDEX);
+    }
+
+    /// Returns reference to the Gemm K coordinate
+    CATLASS_HOST_DEVICE
+    Index &k()
+    {
+        return this->At(K_INDEX);
+    }
+
+    CATLASS_HOST_DEVICE
+    auto GetCoordMN() const
+    {
+        return this->GetCoordByAxis<M_INDEX, N_INDEX>();
+    }
+
+    CATLASS_HOST_DEVICE
+    auto GetCoordMK() const
+    {
+        return this->GetCoordByAxis<M_INDEX, K_INDEX>();
+    }
+
+    CATLASS_HOST_DEVICE
+    auto GetCoordKN() const
+    {
+        return this->GetCoordByAxis<K_INDEX, N_INDEX>();
+    }
+};
+
+} // namespace Catlass
+
+#endif // CATLASS_MSA_GEMM_COORD_HPP

